import{_ as o,l as s,o as e,c as n,v as t,p as l,x as r,d as u,i as E,S as h}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"稳健回归与离群","description":"","frontmatter":{"title":"稳健回归与离群","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/robust-regression-outliers.md","filePath":"quant/robust-regression-outliers.md","lastUpdated":1789023840000}'),p={name:"quant/robust-regression-outliers.md"};function d(c,a,b,A,B,m){const i=s("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="稳健回归与离群" tabindex="-1">稳健回归与离群 <a class="header-anchor" href="#稳健回归与离群" aria-label="Permalink to &quot;稳健回归与离群&quot;">​</a></h1><div class="epigraph"><p>最小二乘把平方残差当作损失；一次闪崩、一次错价、一次合并跳，就能把斜率拽到只服务那几个点，而 t 值还以为样本很大。</p><footer>—— Huber, Robust Estimation of a Location Parameter, Annals of Mathematical Statistics, 1964；高崩溃点见 Rousseeuw 的 LMS/LTS</footer></div><p><a href="/quant/shrinkage-empirical-bayes">收缩</a> 把噪声很大的 \\(\\hat\\theta_i\\) 拉向中心，仍假设大部分点来自同一高斯超总体。金融收益的离群不是同一方差的尾巴那么简单：错误成交、停牌复牌跳、指数一次性调整，会在 \\(x\\) 或 \\(y\\) 上留下高杠杆点。OLS 的影响函数无界，一个点可以任意改 \\(\\hat\\beta\\)。Huber 的 M 估计对残差用缓增的 \\(\\rho\\)；Rousseeuw 的最小截尾二乘把崩溃点提高到将近 50%。本课缺口：在 White/HAC 已经改过<strong>精度</strong>、收缩改过<strong>噪声系数</strong>之后，处理<strong>数据污染</strong>。分位回归留给下一课，对象从「降权离群」换成「直接估条件分位」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>线性模型下 OLS 最小化 \\(\\sum u_i^2\\)。杠杆点 \\(x_i\\) 远离中心且 \\(u_i\\) 大时，对 \\(\\hat\\beta\\) 的影响 \\(\\propto x_i u_i\\)。资产定价月收益里，1987-10、2020-03 对因子斜率的拉力极大。问题是区分三种「大」：</p><ol><li>真尾部风险（要进模型，见 <a href="/quant/garch">GARCH</a> 与跳跃）；</li><li>记录错误（应删或修正，见 tick 清洗）；</li><li>机制不同的体制（应分段或哑变量，而不是假装一个 \\(\\beta\\)）。</li></ol><p>稳健回归默认把 1 的影响限制住，便于估「中心」斜率；它不会自动告诉你属于哪一类。Knez 与 Ready（1997）展示：少数观测可以左右截面定价斜率——对象正是本课。</p><h3 id="崩溃点与效率" tabindex="-1">崩溃点与效率 <a class="header-anchor" href="#崩溃点与效率" aria-label="Permalink to &quot;崩溃点与效率&quot;">​</a></h3><p>Huber \\(\\rho\\) 在中心二次、在尾部线性，高斯下效率高，崩溃点有限（仍可被多维杠杆打穿）。LTS/LMS 崩溃点高，高斯效率低。金融里常用：先诊断杠杆（hat matrix、DFBETA），winsorize \\(y\\) 或 \\(x\\)，再 OLS；或直接 MM 估计（Rousseeuw–Yohai）兼顾效率与崩溃点。没有免费午餐：把危机月全部截尾，估的是「非危机 \\(\\beta\\)」，对风险模型可能是错对象。</p><p><span class="marginnote">winsorize 是改数据再 OLS；Huber 是改损失。两者都引入偏差。报告须写阈值（1%/99% 还是 MAD 倍数），并并列未处理的 OLS——读者才能看见离群是否在驱动结论。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>诊断。</strong> 残差–杠杆图、Cook 距离。时间序列上不要只看截面离群：连续几天的中等残差可以同样拽斜率。面板上按公司看：一家会计丑闻不应决定全样本投资–现金流敏感度。</p><p><strong>估计。</strong> Huber/Bisquare M 估计；对 \\(x\\) 方向用 bounded influence（Schweppe）。标准误用稳健三明治，但注意：已经降权的点，名义 \\(T\\) 不是有效 \\(T\\)。自助应对整段危机块抽样，否则重抽样很少抽到那一次崩盘，区间假窄——接回 <a href="/quant/bootstrap-finance">bootstrap</a> 的块原子。</p><p><strong>定价回归。</strong> 截面 FM 每月 winsorize 特征与收益是行业惯例，等于每月一次稳健化。全样本一次 OLS 对 \\(\\alpha\\) 更脆。不要只在「显著的那一列」winsor。</p><h3 id="与跳跃、微观结构" tabindex="-1">与跳跃、微观结构 <a class="header-anchor" href="#与跳跃、微观结构" aria-label="Permalink to &quot;与跳跃、微观结构&quot;">​</a></h3><p>高频里错价平方就是假跳，应先 <a href="/quant/tick-cleaning">清洗</a>，不是用 Huber 对 tick 回归「稳健一下」。日频因子回归里，跳跃日可以留着但降权，或单独哑变量（事件）。对象是连续 \\(\\beta\\) 还是含跳的平均 \\(\\beta\\)，必须先写。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>OLS 的正规方程 \\(\\sum x_i u_i=0\\) 让大 \\(u_i\\) 获得大投票权。Huber 把 \\(u_i\\) 换成 \\(\\psi(u_i)\\)，\\(\\psi\\) 有界，投票权封顶。LTS 只对残差最小的那 \\((1-\\alpha)n\\) 个点做 OLS，污染点若进不了这组就零投票。机制都是<strong>重新分配影响函数</strong>。代价是：若「污染」其实是真实的因子跳跃，你估的 \\(\\beta\\) 不再对应投资者实际承受的平均暴露。</p><p>经验贝叶斯收缩对所有点平滑；稳健回归对少数点截断。两者可叠加：先稳健估截面超参数，再收缩。顺序要声明，否则无法复现。</p><p><span class="marginnote">删除离群再看 t 值，是数据驱动的设定搜索。预登记规则（例如 \\(|r|\\gt 5\\sigma\\) 且伴随新闻则标为跳）比事后删除不显著点更干净。</span></p><h3 id="多元与协方差" tabindex="-1">多元与协方差 <a class="header-anchor" href="#多元与协方差" aria-label="Permalink to &quot;多元与协方差&quot;">​</a></h3><p>最小协方差行列式（MCD）给稳健 \\(\\Sigma\\)，再进组合或马氏距离洗点。与 Ledoit–Wolf 不同：一个抗污染，一个抗维数。污染加高维时两者都要，但样本会变得很「假干净」。风险系统若用稳健 \\(\\Sigma\\) 而真实 P&amp;L 含跳，VaR 会偏乐观。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>小 \\(N\\) 高崩溃点方法方差极大。事件研究里你要的就是那一个跳，稳健回归会把对象抹掉。固定效应面板里，稳健须与组内变换兼容，对 \\(i\\) 内离群和对 \\(t\\) 的共同跳处理不同。</p><p>工程：默认报告 OLS 与 winsor/Huber 并列；危机哑变量作为第三列。不要用稳健回归替代识别（IV、FE）。不要把「稳健后不显著」写成「效应不存在」——可能只是效应集中在尾部，下一课分位回归正对这个缺口。</p>',25)),(e(),l(h,null,{default:r(()=>[E(i,{id:"mermaid-87",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E7%82%B9%20(x%2Cy)%22%5D%20--%3E%20OLS%5B%22OLS%3A%20%E5%B9%B3%E6%96%B9%E6%8D%9F%E5%A4%B1%20%E5%BD%B1%E5%93%8D%E6%97%A0%E7%95%8C%22%5D%0A%20%20P%20--%3E%20D%5B%22%E8%AF%8A%E6%96%AD%3A%20%E6%9D%A0%E6%9D%86%20%2F%20Cook%22%5D%0A%20%20D%20--%3E%20TYP%7B%22%E7%A6%BB%E7%BE%A4%E7%B1%BB%E5%9E%8B%22%7D%0A%20%20TYP%20--%3E%7C%E9%94%99%E8%AE%B0%E5%BD%95%7C%20CLN%5B%22%E4%BF%AE%E6%AD%A3%E6%88%96%E5%88%A0%E9%99%A4%22%5D%0A%20%20TYP%20--%3E%7C%E7%9C%9F%E5%B0%BE%E9%83%A8%20%2F%20%E8%B7%B3%22%7C%20KEEP%5B%22%E4%BF%9D%E7%95%99%E5%B9%B6%E6%A8%A1%E5%9E%8B%E5%8C%96%20%E6%88%96%20%E9%99%8D%E6%9D%83%22%5D%0A%20%20TYP%20--%3E%7C%E4%B8%AD%E5%BF%83%E6%96%9C%E7%8E%87%E5%AF%B9%E8%B1%A1%22%7C%20HUB%5B%22Huber%20%2F%20LTS%20%2F%20MM%22%5D%0A%20%20HUB%20--%3E%20CMP%5B%22%E4%B8%8E%20OLS%20%E5%B9%B6%E5%88%97%E6%8A%A5%E5%91%8A%22%5D%0A%20%20OLS%20--%3E%20CMP%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[u(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>OLS 对离群影响无界；Huber 类 M 估计限制残差投票权，LTS/MM 提高崩溃点。</li><li>先区分错数据、真跳跃、体制，再决定删、哑变量还是降权。</li><li>稳健化改变对象：估的是中心斜率，不一定是投资者承受的平均 \\(\\beta\\)。</li><li>与收缩、HAC 分工：污染、噪声系数、依赖结构是三件不同的事。</li><li>出处：Huber, <em>Annals of Mathematical Statistics</em>, 1964；Rousseeuw 高崩溃点方法；资产定价中离群影响见 Knez and Ready, <em>Journal of Finance</em>, 1997。</li></ul>',2))])}const f=o(p,[["render",d]]);export{S as __pageData,f as default};
